const s = wb.getWorksheet('Sheet1');
const a = s.getRange('A3:AF14').getValues();
const b = s.getRange('A20:B339').getValues();
const map = {}; a.forEach(r => map[r[0]] = r);
let mism = 0, counts = {num:0, zero:0, text:[], neg:0, err:0};
const epoch = Date.UTC(1899,11,30);
b.forEach(([d,v],i) => { const dt = new Date(epoch + d*86400000); const k = dt.getUTCFullYear()+'-'+String(dt.getUTCMonth()+1).padStart(2,'0'); let e = map[k][dt.getUTCDate()]; if (e==null) e=0; if (e!==v) mism++; if (typeof v==='string') counts.text.push([i+20,k,dt.getUTCDate(),v]); else {counts.num++; if(v===0)counts.zero++; if(v<0)counts.neg++;} });
log(JSON.stringify({mism,counts}));
log(JSON.stringify(b.slice(90,120).map(r=>r[1]))); // Apr 1 to 30 = 1/1 +90
log(s.getRange('A109:B111').getValues(), s.getRange('A339').getText?.(), s.getRange('A20').getStyle().getNumberFormat(), s.getRange('A339').getStyle().getNumberFormat());
log(JSON.stringify(s.getRange('B6:AF6').getValues()[0].filter(x=>x!==null)));
log(JSON.stringify(s.getRange('A15:C17').getValues()));

